/** Bots and the guardian. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    build
 * depends    scripts/game-wiki/render.mjs
 * used by    —
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import { heading, infobox, recordTable, sections, table, titleCase } from '../render.mjs'

export function build(context) {
  const { data } = context.sdk
  const { format } = context
  const bots = data.BOT_UPGRADES_DATA

  const statTable = (order, stats) =>
    table(
      ['Stat', 'Base', 'Per level', 'Levels', 'Unit'],
      order.map(name => [name, format.value(stats[name].base), format.value(stats[name].perLevel), stats[name].maxLevel, stats[name].unit]),
    )
  const costTable = costs => table(['Upgrade', 'Cost'], costs.map((cost, index) => [index, format.cost(cost)]))

  for (const bot of bots) {
    context.page(
      `Bot: ${bot.name}`,
      sections(
        heading(2, 'Stats'),
        statTable(bot.statOrder, bot.stats),
        heading(2, 'Upgrade Costs'),
        costTable(bot.costs),
        heading(2, 'Labs'),
        recordTable(bot.labInfo, format, [['name', 'Lab'], ['maxLevel', 'Levels'], ['maxValue', 'Value at the last level']]),
        bot.plus ? heading(2, `Plus: ${bot.plus.label}`) : '',
        bot.plus ? infobox([['Stone cost to unlock', format.value(bot.plus.unlockStoneCost)]]) : '',
        bot.plus ? statTable(bot.plus.statOrder, bot.plus.stats) : '',
        bot.plus ? costTable(bot.plus.costs) : '',
        `Back to ${context.link('Bots')}.`,
      ),
      { source: 'BOT_UPGRADES_DATA' },
    )
  }

  context.page(
    'Bots',
    sections(
      context.overview('bots'),
      table(['Bot', 'Stats'], bots.map(bot => [context.link(`Bot: ${bot.name}`, bot.name), bot.statOrder.join(', ')])),
    ),
    { source: 'BOT_UPGRADES_DATA' },
  )

  const chips = data.GUARDIANS_ASSET_TABLE
  context.page(
    'Guardian',
    sections(
      context.overview('guardian'),
      heading(2, 'Chips'),
      table(['Chip', 'What it does'], chips.chipNames.map((name, index) => [name, chips.chipDescriptions[index]])),
      ...Object.entries(data.guardianUpgrades).map(([track, rows]) =>
        sections(heading(2, `${titleCase(track)} Upgrades`), recordTable(rows, format)),
      ),
    ),
    { source: ['guardianUpgrades', 'GUARDIANS_ASSET_TABLE'] },
  )

  context.group('Bots and Guardian', ['Bots', 'Guardian'])
}
